import{_ as o,C as s,o as a,c as i,a5 as r,E as l}from"./chunks/framework.CDWg-b0B.js";const k=JSON.parse('{"title":"awesome-claude-skills","description":"A curated list of awesome Claude Skills, resources, and tools for customizing Claude AI workflows","frontmatter":{"title":"awesome-claude-skills","url":"https://github.com/ComposioHQ/awesome-claude-skills","stars":76778,"stars_as_of":"2026-10-10T00:00:00.000Z","stars_source":"github-rest-api","type":"skills","categories":["ai","skills","agents","mcp"],"tags":["agent-skills","claude","claude-code","codex","cursor","gemini-cli","mcp","automation","saas"],"description":"A curated list of awesome Claude Skills, resources, and tools for customizing Claude AI workflows","license":"Apache-2.0","head":[["link",{"rel":"canonical","href":"https://awesome.rairahulr1.com/repos/awesome-claude-skills"}],["meta",{"name":"description","content":"A curated list of awesome Claude Skills, resources, and tools for customizing Claude AI workflows"}],["meta",{"property":"og:type","content":"article"}],["meta",{"property":"og:title","content":"awesome-claude-skills · awesomes"}],["meta",{"property":"og:description","content":"A curated list of awesome Claude Skills, resources, and tools for customizing Claude AI workflows"}],["meta",{"property":"og:url","content":"https://awesome.rairahulr1.com/repos/awesome-claude-skills"}],["meta",{"name":"twitter:card","content":"summary"}],["meta",{"name":"twitter:title","content":"awesome-claude-skills · awesomes"}],["meta",{"name":"twitter:description","content":"A curated list of awesome Claude Skills, resources, and tools for customizing Claude AI workflows"}],["script",{"type":"application/ld+json"},"{\\"@context\\":\\"https://schema.org\\",\\"@type\\":\\"SoftwareSourceCode\\",\\"name\\":\\"awesome-claude-skills\\",\\"description\\":\\"A curated list of awesome Claude Skills, resources, and tools for customizing Claude AI workflows\\",\\"codeRepository\\":\\"https://github.com/ComposioHQ/awesome-claude-skills\\",\\"license\\":\\"Apache-2.0\\",\\"interactionStatistic\\":{\\"@type\\":\\"InteractionCounter\\",\\"interactionType\\":\\"https://schema.org/LikeAction\\",\\"userInteractionCount\\":76778}}"]]},"headers":[],"relativePath":"repos/awesome-claude-skills.md","filePath":"repos/awesome-claude-skills.md","lastUpdated":1791637702000}'),n={name:"repos/awesome-claude-skills.md"};function c(d,e,m,u,p,h){const t=s("Comments");return a(),i("div",null,[e[0]||(e[0]=r('<h1 id="awesome-claude-skills" tabindex="-1">awesome-claude-skills <a class="header-anchor" href="#awesome-claude-skills" aria-label="Permalink to &quot;awesome-claude-skills&quot;">​</a></h1><blockquote><p>A curated list of awesome Claude Skills, resources, and tools for customizing Claude AI workflows.</p></blockquote><p><strong>Source:</strong> <a href="https://github.com/ComposioHQ/awesome-claude-skills" target="_blank" rel="noreferrer">github.com/ComposioHQ/awesome-claude-skills</a> · ★ 76.7k · Apache-2.0 · the only 77-commit repo in this index with 1.5k open PRs</p><h2 id="what-a-skill-is-from-the-source" tabindex="-1">What a skill is (from the source) <a class="header-anchor" href="#what-a-skill-is-from-the-source" aria-label="Permalink to &quot;What a skill is (from the source)&quot;">​</a></h2><p>Claude Skills are reusable instruction packages that teach an agent how to handle a class of tasks. Each skill is a folder with a <code>SKILL.md</code> (YAML frontmatter + markdown), optionally bundled with scripts, references and assets. Anthropic introduced the format in October 2025 and open-sourced it in December 2025; it now works across Claude Code, Claude.ai, the Claude API, OpenAI Codex, Cursor, Gemini CLI, Antigravity and Windsurf.</p><p>Skills load <strong>progressively</strong>: at session start the agent sees only each skill&#39;s name and description (~100 tokens each). The body loads only when the agent judges it relevant. That is what lets one agent host hundreds of skills without blowing its context window.</p><p>Skills are not MCP servers and not tools. MCP handles connection (auth, transport, discovery), tools are the individual functions invoked, skills define the workflow and guardrails. In production all three layers run together.</p><h2 id="what-s-inside" tabindex="-1">What&#39;s inside <a class="header-anchor" href="#what-s-inside" aria-label="Permalink to &quot;What&#39;s inside&quot;">​</a></h2><ul><li><strong>Document processing</strong> — Anthropic&#39;s own <code>docx</code>, <code>pdf</code>, <code>pptx</code>, <code>xlsx</code> skills; Markdown→EPUB; a legal-team skill pack (NDA triage, multi-party diff, citation verifier) built from Anthropic&#39;s public webinar dataset</li><li><strong>Development &amp; code tools</strong> — artifacts-builder, AWS CDK skills, blog generator (Next.js + Sanity, SEO/i18n intake → spec → generator), changelog generator, Chrome Relay (drives your <em>real</em> logged-in Chrome, not Playwright), terminal titles, D3.js viz, FFUF fuzzing, <code>finishing-a-development-branch</code>, full-page screenshot, <code>great_cto</code> (7 subagents, 11 archetypes, 13 compliance frameworks), iOS Simulator, Jules delegation, LangSmith fetch, <code>lean-ctx</code> (90+ shell patterns, token reduction), MCP builder, code-quality checks, OpenWeb (calls sites&#39; own APIs — 90+ sites), Playwright automation, prompt engineering, PICT combinatorial testing, reddit-fetch (works around WebFetch 403s), subagent-driven development, test-driven development, git worktrees, webapp testing</li><li><strong>Data &amp; analysis</strong> — CSV summariser, deep research (Gemini DR agent), read-only Postgres with multi-connection + defence in depth, recursive PhD-level research with disk checkpoints, root-cause tracing</li><li><strong>Business &amp; marketing</strong> — 59-skill brand library with an Ahrefs SEO audit suite, Anthropic brand guidelines, competitive ads extractor, domain name brainstormer, internal comms (3P updates, newsletters, FAQs), lead research assistant</li><li><strong>Communication &amp; writing</strong> — article extractor, brainstorming, content research writer, family-history research, meeting insight analyser (conflict avoidance, speaking ratios, filler words), NotebookLM integration, Twitter algorithm optimiser</li><li><strong>Creative &amp; media</strong> — design-system extractor (<code>design.md</code> portable to v0/Lovable/Cursor), canvas design, Imagen, image enhancer, Slack GIF creator, theme factory (10 presets), video downloader, YouTube transcript, SwiftUI design skill (anti-AI-slop rules, supports Claude Code/Cursor/Codex/OpenCode), Pixelbin media generation</li><li><strong>Productivity &amp; organisation</strong> — file organiser (finds duplicates), invoice organiser, kaizen, n8n skills, raffle picker (CSPRNG), solo-skills (EN+中文, explicit &quot;when NOT to use&quot; sections), tailored resume generator, ship-learn-next, tapestry (documents → knowledge networks)</li><li><strong>Collaboration &amp; project management</strong> — git-pushing, Google Workspace (Gmail/Calendar/Docs/Sheets/Slides/Drive), Mercury/Proton team cheatsheet, Outline, review-implementing, test-fixing, computer forensics (metadata extraction, file deletion), Sigma threat hunting</li><li><strong>Security &amp; systems</strong> — computer forensics skills, threat hunting with Sigma rules</li><li><strong>Assistive technology</strong> — ASD/AuDHD/PAI skills, including persistent-demand-avoidance reframing</li><li><strong>App automation via Composio (Rube MCP)</strong> — pre-built workflow skills for <strong>78 SaaS apps</strong>, each with tool sequences, parameter guidance and known pitfalls <ul><li>CRM &amp; sales: Close, HubSpot, Pipedrive, Salesforce, Zoho</li><li>Project management: Asana, Basecamp, ClickUp, Jira, Linear, Monday, Notion, Todoist, Trello, Wrike</li><li>Communication: Discord, Intercom, Microsoft Teams, Slack, Telegram, WhatsApp</li><li>Email: Gmail, Outlook, Postmark, SendGrid</li><li>Code &amp; DevOps: Bitbucket, CircleCI, Datadog, GitHub, GitLab, PagerDuty, Render, Sentry, Supabase, Vercel</li><li>Storage &amp; files: Box, Dropbox, Google Drive, OneDrive</li><li>Spreadsheets &amp; databases: Airtable, Coda</li></ul></li></ul><h2 id="notes" tabindex="-1">Notes <a class="header-anchor" href="#notes" aria-label="Permalink to &quot;Notes&quot;">​</a></h2><ul><li>This is commercially motivated — the repo is the funnel for Composio&#39;s MCP Gateway. The skills themselves are genuine; the &quot;give your skills real-world actions&quot; section is the pitch.</li><li><code>connect-apps</code> is the load-bearing plugin: everything in the automation section depends on it.</li></ul>',11)),l(t)])}const w=o(n,[["render",c]]);export{k as __pageData,w as default};
